def sort_versions(versions):
    def parse_semver(v):
        # Split into base version and prerelease
        if '-' in v:
            base, pre = v.split('-', 1)
        else:
            base, pre = v, None

        # Parse base version (major.minor.patch)
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse prerelease identifiers
        pre_ids = []
        if pre:
            for ident in pre.split('.'):
                if ident.isdigit():
                    pre_ids.append(int(ident))
                else:
                    pre_ids.append((0, ident))  # (numeric_flag, string) for non-numeric

        return (major, minor, patch, pre_ids)

    return sorted(versions, key=parse_semver)
